const http = require("node:http");
const server = http.createServer((req, res) => {
  const ok = req.method === "GET" && req.url === "/api/tasks";
  res.writeHead(ok ? 200 : 404, {"Content-Type":"application/json; charset=utf-8"});
  res.end(JSON.stringify(ok
    ? {tasks:[{id:"t1",title:"演示任务",done:false}]}
    : {error:{code:"NOT_FOUND",message:"接口不存在"}}));
});
server.listen(4100, "127.0.0.1", () => console.log("http://127.0.0.1:4100/api/tasks"));

async function loadTasks() {
  loading = true; render();
  try {
    const response = await fetch("/api/tasks");
    if (!response.ok) throw new Error("读取失败：" + response.status);
    const data = await response.json();
    tasks = validateTasks(data.tasks); // 返回合法数组，否则抛错
  } catch (error) { showError(error.message); }
  finally { loading = false; render(); }
}

function validTitle(value) {
  return typeof value === "string"
    && value.trim().length > 0
    && value.trim().length <= 120;
}
